// Builds the 3D object for an item, always at its real size (1 unit = 1 metre).
// Origin: floor items sit on y=0 centred on x/z; wall items have their back on z=0 and their bottom on y=0.
// The front faces +Z. Three ways to draw an item:
//   shape  - drawn by the app for its category, in the item's colour (instant, works offline)
//   photo  - the product photo, background removed, standing at its real width and height
//   glb    - a real 3D model (from the store page or generated by AI), stretched to the real dimensions
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { CATEGORIES } from './catalog.js';

const M = v => v / 100;
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

// ---------- materials ----------
function shade(hex, amount) {
  const c = new THREE.Color(hex);
  const hsl = {}; c.getHSL(hsl);
  c.setHSL(hsl.h, hsl.s, clamp(hsl.l + amount, 0, 1));
  return c;
}
const fabric = (hex, rough = 0.92) => new THREE.MeshPhysicalMaterial({
  color: new THREE.Color(hex), roughness: rough, metalness: 0,
  sheen: 0.7, sheenRoughness: 0.75, sheenColor: shade(hex, 0.18),
});
const wood = hex => new THREE.MeshStandardMaterial({ color: new THREE.Color(hex), roughness: 0.58, metalness: 0 });
const matte = hex => new THREE.MeshStandardMaterial({ color: new THREE.Color(hex), roughness: 0.75, metalness: 0 });
const metal = hex => new THREE.MeshStandardMaterial({ color: new THREE.Color(hex), roughness: 0.32, metalness: 0.85 });
const LEG = '#2B2622';

function rbox(w, h, d, r, mat) {
  const rr = clamp(r, 0.002, Math.min(w, h, d) / 2 - 0.001);
  const mesh = new THREE.Mesh(new RoundedBoxGeometry(w, h, d, 2, rr), mat);
  mesh.castShadow = mesh.receiveShadow = true;
  return mesh;
}
function cyl(rt, rb, h, mat, seg = 28, open = false) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg, 1, open), mat);
  mesh.castShadow = mesh.receiveShadow = true;
  return mesh;
}
const at = (mesh, x, y, z) => { mesh.position.set(x, y, z); return mesh; };

// A seeded random so the same item always gets the same books and leaves.
function rng(seed) {
  let s = 0;
  for (const ch of String(seed)) s = (s * 31 + ch.charCodeAt(0)) >>> 0;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
}

// ---------- builders: (W, D, H in metres, item) -> Group ----------
function legs(g, W, D, legH, inset, mat, r = 0.018, taper = 0.7) {
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    g.add(at(cyl(r * taper, r, legH, mat, 12), sx * (W / 2 - inset), legH / 2, sz * (D / 2 - inset)));
  }
}

function sofa(W, D, H, item, seats) {
  const g = new THREE.Group();
  const body = fabric(item.color);
  const cushion = fabric(shade(item.color, 0.04).getStyle());
  const legH = clamp(H * 0.12, 0.05, 0.14);
  const seatTop = clamp(H * 0.55, 0.36, 0.5);
  const cushT = clamp(seatTop * 0.3, 0.08, 0.16);
  const arm = clamp(W * 0.09, 0.07, 0.2);
  const armH = Math.min(H, seatTop + clamp(H * 0.2, 0.1, 0.22));
  const back = clamp(D * 0.2, 0.12, 0.24);
  const baseH = seatTop - cushT - legH;
  g.add(at(rbox(W, baseH, D, 0.03, body), 0, legH + baseH / 2, 0));
  for (const s of [-1, 1]) g.add(at(rbox(arm, armH - legH, D, 0.04, body), s * (W / 2 - arm / 2), legH + (armH - legH) / 2, 0));
  g.add(at(rbox(W - 0.004, H - legH, back, 0.04, body), 0, legH + (H - legH) / 2, -D / 2 + back / 2));
  const n = seats ?? (W - 2 * arm > 1.7 ? 3 : W - 2 * arm > 1.05 ? 2 : 1);
  const inner = W - 2 * arm;
  const cw = inner / n;
  const cd = D - back - 0.01;
  for (let i = 0; i < n; i++) {
    const x = -inner / 2 + cw * (i + 0.5);
    g.add(at(rbox(cw - 0.012, cushT, cd, 0.045, cushion), x, seatTop - cushT / 2, -D / 2 + back + cd / 2));
    const bh = clamp((H - seatTop) * 0.82, 0.1, 0.5);
    const bc = at(rbox(cw - 0.03, bh, 0.15, 0.06, cushion), x, seatTop + bh / 2 - 0.01, -D / 2 + back + 0.07);
    bc.rotation.x = -0.12;
    g.add(bc);
  }
  legs(g, W, D, legH, 0.06, wood(LEG), 0.02);
  return g;
}

function chair(W, D, H, item) {
  const g = new THREE.Group();
  const w = wood(item.color);
  const seatH = clamp(H * 0.55, 0.4, 0.48);
  const t = 0.03;
  g.add(at(rbox(W, t, D, 0.01, w), 0, seatH, 0));
  const legH = seatH - t / 2;
  legs(g, W, D, legH, 0.035, w, 0.017, 0.75);
  // back rest: two posts and a curved rail
  for (const s of [-1, 1]) g.add(at(cyl(0.013, 0.015, H - seatH, w, 10), s * (W / 2 - 0.035), seatH + (H - seatH) / 2, -D / 2 + 0.035));
  g.add(at(rbox(W - 0.02, clamp((H - seatH) * 0.35, 0.06, 0.14), 0.02, 0.008, w), 0, H - 0.07, -D / 2 + 0.035));
  return g;
}

function bed(W, D, H, item) {
  const g = new THREE.Group();
  const body = fabric(item.color);
  const legH = 0.08;
  const frameH = 0.26;
  g.add(at(rbox(W, frameH, D, 0.03, body), 0, legH + frameH / 2, 0));
  const mattH = 0.22;
  const mattTop = legH + frameH + mattH;
  g.add(at(rbox(W - 0.06, mattH, D - 0.1, 0.06, fabric('#F1EFEA')), 0, legH + frameH + mattH / 2, 0.02));
  // duvet over the foot two thirds
  const duvetD = (D - 0.1) * 0.68;
  g.add(at(rbox(W - 0.03, 0.06, duvetD, 0.03, fabric(shade(item.color, 0.12).getStyle())), 0, mattTop + 0.01, D / 2 - 0.04 - duvetD / 2));
  const headH = Math.max(H, mattTop + 0.25);
  g.add(at(rbox(W + 0.02, headH - legH, 0.09, 0.04, body), 0, legH + (headH - legH) / 2, -D / 2 + 0.045));
  const pillows = W > 1.25 ? 2 : 1;
  const pw = (W - 0.2) / pillows;
  for (let i = 0; i < pillows; i++) {
    const p = at(rbox(pw - 0.06, 0.13, 0.42, 0.06, fabric('#FAF9F6')), -W / 2 + 0.1 + pw * (i + 0.5), mattTop + 0.07, -D / 2 + 0.36);
    p.rotation.x = -0.25;
    g.add(p);
  }
  legs(g, W, D, legH, 0.08, wood(LEG), 0.025, 1);
  return g;
}

function table(W, D, H, item, coffee) {
  const g = new THREE.Group();
  const w = wood(item.color);
  const t = coffee ? 0.04 : 0.035;
  const round = item.shape === 'round' || (coffee && Math.abs(W - D) < 0.06);
  if (round) {
    const r = Math.min(W, D) / 2;
    g.add(at(cyl(r, r, t, w, 64), 0, H - t / 2, 0));
    if (coffee) {
      g.add(at(cyl(r * 0.86, r * 0.86, H - t, w, 48), 0, (H - t) / 2, 0));
    } else {
      g.add(at(cyl(0.05, 0.07, H - t, w, 20), 0, (H - t) / 2, 0));
      g.add(at(cyl(r * 0.45, r * 0.5, 0.03, w, 40), 0, 0.015, 0));
    }
    return g;
  }
  g.add(at(rbox(W, t, D, 0.008, w), 0, H - t / 2, 0));
  legs(g, W, D, H - t, coffee ? 0.06 : 0.07, w, coffee ? 0.02 : 0.025, 0.7);
  if (coffee) g.add(at(rbox(W - 0.14, 0.02, D - 0.14, 0.006, w), 0, H * 0.3, 0));
  return g;
}

function shelf(W, D, H, item) {
  const g = new THREE.Group();
  const w = wood(item.color);
  const t = 0.022;
  for (const s of [-1, 1]) g.add(at(rbox(t, H, D, 0.004, w), s * (W / 2 - t / 2), H / 2, 0));
  g.add(at(rbox(W, t, D, 0.004, w), 0, H - t / 2, 0));
  const back = at(new THREE.Mesh(new THREE.PlaneGeometry(W - 2 * t, H - t), matte(shade(item.color, -0.08).getStyle())), 0, H / 2, -D / 2 + 0.004);
  back.receiveShadow = true;
  g.add(back);
  const n = Math.max(2, Math.round(H / 0.36));
  const gap = (H - t) / n;
  const rand = rng(item.id || item.name);
  // books share one box and a few materials, which keeps the AR file small
  const bookMats = ['#3E4247', '#E6E1D8', '#5E7C93', '#B65E45', '#8F9E8B', '#C9962E', '#F1EFEA'].map(matte);
  const bookGeo = new THREE.BoxGeometry(1, 1, 1);
  for (let i = 0; i < n; i++) {
    const y = i * gap;
    g.add(at(rbox(W - 2 * t, t, D, 0.003, w), 0, y + t / 2, 0));
    // books on most shelves, leaving some breathing room
    if (i === 0 || rand() < 0.2) continue;
    let x = -W / 2 + t + 0.02;
    const end = W / 2 - t - 0.02 - (rand() < 0.5 ? (W - 2 * t) * 0.35 : 0);
    while (x < end) {
      const bw = 0.02 + rand() * 0.025;
      const bh = Math.min(gap - t - 0.02, 0.17 + rand() * 0.1);
      const bd = Math.min(D - 0.04, 0.16 + rand() * 0.06);
      if (x + bw > end) break;
      const book = new THREE.Mesh(bookGeo, bookMats[Math.floor(rand() * bookMats.length)]);
      book.scale.set(bw, bh, bd);
      book.castShadow = book.receiveShadow = true;
      g.add(at(book, x + bw / 2, y + t + bh / 2, -D / 2 + 0.02 + bd / 2));
      x += bw + 0.002;
    }
  }
  return g;
}

function cabinet(W, D, H, item) {
  const g = new THREE.Group();
  const w = wood(item.color);
  const legH = H > 0.35 ? clamp(H * 0.18, 0.06, 0.16) : 0;
  const bodyH = H - legH;
  g.add(at(rbox(W, bodyH, D, 0.01, w), 0, legH + bodyH / 2, 0));
  const doors = Math.max(2, Math.round(W / 0.45));
  const dw = (W - 0.03) / doors;
  const front = wood(shade(item.color, 0.03).getStyle());
  for (let i = 0; i < doors; i++) {
    const x = -W / 2 + 0.015 + dw * (i + 0.5);
    g.add(at(rbox(dw - 0.006, bodyH - 0.03, 0.012, 0.003, front), x, legH + bodyH / 2, D / 2 + 0.004));
    g.add(at(rbox(0.012, 0.09, 0.016, 0.005, metal('#B9B4AC')), x + (i % 2 ? -1 : 1) * (dw / 2 - 0.04), legH + bodyH * 0.6, D / 2 + 0.016));
  }
  if (legH) legs(g, W, D, legH, 0.06, wood(LEG), 0.016, 0.6);
  return g;
}

function lamp(W, D, H, item) {
  const g = new THREE.Group();
  const r = Math.min(W, D) / 2;
  const floorLamp = H > 0.9;
  const baseM = metal('#2B2622');
  if (floorLamp) {
    g.add(at(cyl(r * 0.62, r * 0.68, 0.025, baseM, 40), 0, 0.0125, 0));
    const shadeH = clamp(H * 0.2, 0.18, 0.38);
    g.add(at(cyl(0.008, 0.008, H - shadeH * 0.6, baseM, 10), 0, (H - shadeH * 0.6) / 2, 0));
    const shadeMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(item.color), roughness: 0.9, side: THREE.DoubleSide, emissive: new THREE.Color('#FFD9A0'), emissiveIntensity: 0.35 });
    g.add(at(cyl(r * 0.7, r, shadeH, shadeMat, 40, true), 0, H - shadeH / 2, 0));
  } else {
    const baseH = H * 0.55;
    g.add(at(cyl(r * 0.35, r * 0.5, baseH, matte(item.color), 40), 0, baseH / 2, 0));
    const shadeMat = new THREE.MeshStandardMaterial({ color: new THREE.Color('#F1EFEA'), roughness: 0.9, side: THREE.DoubleSide, emissive: new THREE.Color('#FFD9A0'), emissiveIntensity: 0.35 });
    g.add(at(cyl(r * 0.7, r, H - baseH, shadeMat, 40, true), 0, baseH + (H - baseH) / 2, 0));
  }
  const bulb = new THREE.PointLight('#FFD9A0', 0.6, 3, 2);
  bulb.position.set(0, H * 0.88, 0);
  bulb.userData.helper = true;
  g.add(bulb);
  return g;
}

function plant(W, D, H, item) {
  const g = new THREE.Group();
  const r = Math.min(W, D) / 2;
  const potH = clamp(H * 0.28, 0.15, 0.45);
  const potR = clamp(r * 0.5, 0.08, 0.3);
  g.add(at(cyl(potR, potR * 0.78, potH, matte('#E6E1D8'), 36), 0, potH / 2, 0));
  g.add(at(cyl(potR * 0.94, potR * 0.94, 0.01, matte('#4A3B30'), 36), 0, potH - 0.02, 0));
  const rand = rng(item.id || item.name || 'plant');
  const leafGeo = new THREE.SphereGeometry(1, 14, 10);
  const greens = [item.color || '#4F6B4A', '#5D7A55', '#41583D', '#6B8A60'];
  const stemM = matte('#5B6B3E');
  const count = Math.round(9 + H * 6);
  for (let i = 0; i < count; i++) {
    const a = rand() * Math.PI * 2;
    const t = 0.25 + rand() * 0.75;
    const y = potH + (H - potH) * t * 0.92;
    const spread = (r - 0.05) * (0.35 + 0.65 * Math.sin(t * Math.PI * 0.9));
    const x = Math.cos(a) * spread, z = Math.sin(a) * spread;
    const stemLen = Math.hypot(x, y - potH, z);
    const stem = cyl(0.004, 0.006, stemLen, stemM, 6);
    stem.position.set(x / 2, potH + (y - potH) / 2, z / 2);
    stem.lookAt(x, y, z); stem.rotateX(Math.PI / 2);
    g.add(stem);
    const size = clamp(r * (0.28 + rand() * 0.22), 0.06, 0.3);
    const leaf = new THREE.Mesh(leafGeo, new THREE.MeshStandardMaterial({ color: new THREE.Color(greens[i % greens.length]), roughness: 0.6, side: THREE.DoubleSide }));
    leaf.scale.set(size, size * 0.12, size * 0.7);
    leaf.position.set(x, y, z);
    leaf.rotation.set((rand() - 0.5) * 0.9, -a, (rand() - 0.5) * 0.6 - 0.3);
    leaf.castShadow = true;
    g.add(leaf);
  }
  return g;
}

function rugTexture(item, img) {
  const c = document.createElement('canvas');
  c.width = 512; c.height = Math.round(512 * (item.dims.d / item.dims.w)) || 512;
  const x = c.getContext('2d');
  if (img) { x.drawImage(img, 0, 0, c.width, c.height); }
  else {
    x.fillStyle = item.color; x.fillRect(0, 0, c.width, c.height);
    x.strokeStyle = shade(item.color, 0.14).getStyle(); x.lineWidth = c.width * 0.035;
    x.strokeRect(c.width * 0.06, c.width * 0.06, c.width * 0.88, c.height - c.width * 0.12);
    x.globalAlpha = 0.1; x.fillStyle = '#000';
    const rand = rng(item.id || item.name);
    for (let i = 0; i < 4000; i++) x.fillRect(rand() * c.width, rand() * c.height, 1.5, 1.5);
  }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4;
  return t;
}

function rug(W, D, H, item, img) {
  const g = new THREE.Group();
  const h = Math.max(H, 0.008);
  const side = matte(shade(item.color, -0.06).getStyle());
  const top = new THREE.MeshStandardMaterial({ map: rugTexture(item, img), roughness: 0.98 });
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(W, h, D), [side, side, top, side, side, side]);
  mesh.position.y = h / 2;
  mesh.receiveShadow = true;
  g.add(mesh);
  return g;
}

function abstractArt(item) {
  const c = document.createElement('canvas');
  c.width = 400; c.height = Math.round(400 * (item.dims.h / item.dims.w));
  const x = c.getContext('2d');
  x.fillStyle = '#EFECE6'; x.fillRect(0, 0, c.width, c.height);
  const rand = rng(item.id || item.name);
  const cols = [item.color, '#3E4247', '#C9962E', '#8F9E8B', '#E6E1D8'];
  for (let i = 0; i < 5; i++) {
    x.fillStyle = cols[i % cols.length];
    x.globalAlpha = 0.9;
    x.beginPath();
    const cx = rand() * c.width, cy = rand() * c.height, rr = (0.15 + rand() * 0.3) * c.width;
    if (i % 2) x.arc(cx, cy, rr, 0, Math.PI * 2); else x.rect(cx - rr / 2, cy - rr, rr, rr * 1.4);
    x.fill();
  }
  return c;
}

function art(W, D, H, item, img) {
  const g = new THREE.Group();
  const frameT = clamp(Math.min(W, H) * 0.03, 0.012, 0.04);
  const depth = clamp(D, 0.015, 0.06);
  const frame = wood(item.frame || '#1E1F21');
  g.add(at(rbox(W, frameT, depth, 0.003, frame), 0, H - frameT / 2, depth / 2));
  g.add(at(rbox(W, frameT, depth, 0.003, frame), 0, frameT / 2, depth / 2));
  g.add(at(rbox(frameT, H, depth, 0.003, frame), -W / 2 + frameT / 2, H / 2, depth / 2));
  g.add(at(rbox(frameT, H, depth, 0.003, frame), W / 2 - frameT / 2, H / 2, depth / 2));
  const tex = new THREE.CanvasTexture(img ? toCanvas(img) : abstractArt(item));
  tex.colorSpace = THREE.SRGBColorSpace;
  const pic = new THREE.Mesh(new THREE.PlaneGeometry(W - 2 * frameT, H - 2 * frameT), new THREE.MeshStandardMaterial({ map: tex, roughness: 0.85 }));
  pic.position.set(0, H / 2, depth * 0.55);
  pic.receiveShadow = true;
  g.add(pic);
  g.add(at(new THREE.Mesh(new THREE.BoxGeometry(W - 0.01, H - 0.01, depth * 0.5), matte('#DDD8CF')), 0, H / 2, depth * 0.25));
  return g;
}

function mirror(W, D, H, item) {
  const g = new THREE.Group();
  const glass = new THREE.MeshStandardMaterial({ color: '#DCE3E8', metalness: 1, roughness: 0.04 });
  const frame = metal(item.color);
  const round = item.shape === 'round' || Math.abs(W - H) < 0.04;
  if (round) {
    const r = Math.min(W, H) / 2;
    const ring = new THREE.Mesh(new THREE.TorusGeometry(r - 0.012, 0.012, 16, 80), frame);
    ring.position.set(0, r, 0.02); ring.castShadow = true;
    g.add(ring);
    const disc = new THREE.Mesh(new THREE.CircleGeometry(r - 0.012, 64), glass);
    disc.position.set(0, r, 0.012);
    g.add(disc);
  } else {
    const t = 0.02;
    g.add(at(rbox(W, H, 0.02, 0.006, frame), 0, H / 2, 0.01));
    const pane = new THREE.Mesh(new THREE.PlaneGeometry(W - 2 * t, H - 2 * t), glass);
    pane.position.set(0, H / 2, 0.0205);
    g.add(pane);
  }
  return g;
}

function tv(W, D, H, item) {
  const g = new THREE.Group();
  const depth = clamp(D, 0.02, 0.08);
  g.add(at(rbox(W, H, depth, 0.004, matte('#141517')), 0, H / 2, depth / 2));
  const c = document.createElement('canvas'); c.width = 256; c.height = 144;
  const x = c.getContext('2d');
  const grd = x.createLinearGradient(0, 0, 256, 144);
  grd.addColorStop(0, '#1C2733'); grd.addColorStop(1, '#0B0E12');
  x.fillStyle = grd; x.fillRect(0, 0, 256, 144);
  const tex = new THREE.CanvasTexture(c); tex.colorSpace = THREE.SRGBColorSpace;
  const screen = new THREE.Mesh(new THREE.PlaneGeometry(W - 0.012, H - 0.012), new THREE.MeshStandardMaterial({ map: tex, roughness: 0.15, metalness: 0.2 }));
  screen.position.set(0, H / 2, depth + 0.0008);
  g.add(screen);
  return g;
}

function decor(W, D, H, item) {
  const g = new THREE.Group();
  const r = Math.min(W, D) / 2;
  const pts = [];
  for (let i = 0; i <= 20; i++) {
    const t = i / 20;
    const prof = 0.55 + 0.45 * Math.sin(Math.PI * (0.15 + t * 0.85)) - 0.25 * Math.max(0, t - 0.75) * 4;
    pts.push(new THREE.Vector2(Math.max(0.01, r * prof), H * t));
  }
  const vase = new THREE.Mesh(new THREE.LatheGeometry(pts, 48), new THREE.MeshStandardMaterial({ color: new THREE.Color(item.color), roughness: 0.35, side: THREE.DoubleSide }));
  vase.castShadow = true;
  g.add(vase);
  return g;
}

function box(W, D, H, item) {
  const g = new THREE.Group();
  g.add(at(rbox(W, H, D, Math.min(W, D, H) * 0.08, matte(item.color)), 0, H / 2, 0));
  return g;
}

// ---------- photo cutout ----------
function toCanvas(img) {
  if (img instanceof HTMLCanvasElement) return img;
  const c = document.createElement('canvas');
  c.width = img.naturalWidth || img.width; c.height = img.naturalHeight || img.height;
  c.getContext('2d').drawImage(img, 0, 0);
  return c;
}

/**
 * Removes a plain studio background (white or light grey, as on most store photos) by flood-filling
 * from the edges, then crops to the product. Returns a canvas with transparency, or the original
 * image when the background isn't plain enough to remove safely.
 */
export function cutoutImage(img, tolerance = 30) {
  const max = 900;
  const scale = Math.min(1, max / Math.max(img.naturalWidth || img.width, img.naturalHeight || img.height));
  const w = Math.max(2, Math.round((img.naturalWidth || img.width) * scale));
  const h = Math.max(2, Math.round((img.naturalHeight || img.height) * scale));
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const x = c.getContext('2d', { willReadFrequently: true });
  x.drawImage(img, 0, 0, w, h);
  let data;
  try { data = x.getImageData(0, 0, w, h); } catch { return { canvas: c, removed: false }; }
  const p = data.data;
  // background colour = median of the border pixels
  const border = [];
  for (let i = 0; i < w; i += 3) { border.push(i, (h - 1) * w + i); }
  for (let j = 0; j < h; j += 3) { border.push(j * w, j * w + w - 1); }
  const lum = idx => p[idx * 4] + p[idx * 4 + 1] + p[idx * 4 + 2];
  const sorted = border.slice().sort((a, b) => lum(a) - lum(b));
  const mid = sorted[Math.floor(sorted.length / 2)];
  const bg = [p[mid * 4], p[mid * 4 + 1], p[mid * 4 + 2]];
  const alreadyTransparent = border.filter(i => p[i * 4 + 3] < 20).length / border.length > 0.6;
  const near = idx => Math.abs(p[idx * 4] - bg[0]) + Math.abs(p[idx * 4 + 1] - bg[1]) + Math.abs(p[idx * 4 + 2] - bg[2]) < tolerance * 3;
  const plainBorder = border.filter(near).length / border.length;
  if (!alreadyTransparent) {
    if (plainBorder < 0.7) return { canvas: c, removed: false };
    const seen = new Uint8Array(w * h);
    const stack = border.filter(near);
    stack.forEach(i => { seen[i] = 1; });
    while (stack.length) {
      const i = stack.pop();
      p[i * 4 + 3] = 0;
      const xx = i % w, yy = (i / w) | 0;
      const nb = [xx > 0 ? i - 1 : -1, xx < w - 1 ? i + 1 : -1, yy > 0 ? i - w : -1, yy < h - 1 ? i + w : -1];
      for (const n of nb) if (n >= 0 && !seen[n] && near(n)) { seen[n] = 1; stack.push(n); }
    }
    // soften the edge: pixels next to removed ones become half transparent
    for (let i = 0; i < w * h; i++) {
      if (p[i * 4 + 3] === 0) continue;
      const xx = i % w, yy = (i / w) | 0;
      if ((xx > 0 && p[(i - 1) * 4 + 3] === 0) || (xx < w - 1 && p[(i + 1) * 4 + 3] === 0) || (yy > 0 && p[(i - w) * 4 + 3] === 0) || (yy < h - 1 && p[(i + w) * 4 + 3] === 0)) p[i * 4 + 3] = 140;
    }
    x.putImageData(data, 0, 0);
  }
  // crop to the opaque area
  let x0 = w, y0 = h, x1 = 0, y1 = 0;
  for (let yy = 0; yy < h; yy++) for (let xx = 0; xx < w; xx++) {
    if (p[(yy * w + xx) * 4 + 3] > 40) { if (xx < x0) x0 = xx; if (xx > x1) x1 = xx; if (yy < y0) y0 = yy; if (yy > y1) y1 = yy; }
  }
  if (x1 <= x0 || y1 <= y0) return { canvas: c, removed: false };
  const out = document.createElement('canvas');
  out.width = x1 - x0 + 1; out.height = y1 - y0 + 1;
  out.getContext('2d').drawImage(c, x0, y0, out.width, out.height, 0, 0, out.width, out.height);
  return { canvas: out, removed: true };
}

/** The dominant non-background colour of a product photo, for drawing the item's shape. */
export function dominantColor(canvas) {
  const s = 48;
  const c = document.createElement('canvas'); c.width = s; c.height = s;
  const x = c.getContext('2d', { willReadFrequently: true });
  x.drawImage(canvas, 0, 0, s, s);
  let d;
  try { d = x.getImageData(0, 0, s, s).data; } catch { return null; }
  const buckets = new Map();
  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] < 128) continue;
    const r = d[i], g = d[i + 1], b = d[i + 2];
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    if (mn > 238) continue; // background white
    const key = ((r >> 5) << 6) | ((g >> 5) << 3) | (b >> 5);
    const e = buckets.get(key) || { n: 0, r: 0, g: 0, b: 0 };
    // favour saturated, mid-tone pixels over shadows and highlights
    const wgt = 1 + (mx - mn) / 64 - Math.abs((mx + mn) / 2 - 128) / 256;
    e.n += wgt; e.r += r * wgt; e.g += g * wgt; e.b += b * wgt;
    buckets.set(key, e);
  }
  let best = null;
  for (const e of buckets.values()) if (!best || e.n > best.n) best = e;
  if (!best) return null;
  return '#' + [best.r, best.g, best.b].map(v => Math.round(v / best.n).toString(16).padStart(2, '0')).join('');
}

function photo(W, D, H, item, img) {
  const g = new THREE.Group();
  const tex = new THREE.CanvasTexture(toCanvas(img));
  tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 4;
  const mat = new THREE.MeshStandardMaterial({ map: tex, transparent: true, alphaTest: 0.25, side: THREE.DoubleSide, roughness: 0.9 });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(W, H), mat);
  plane.position.set(0, H / 2, CATEGORIES[item.category]?.mount === 'wall' ? 0.005 : 0);
  plane.castShadow = true;
  // the shadow uses the photo's outline instead of the whole rectangle
  plane.customDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking, map: tex, alphaTest: 0.25 });
  g.add(plane);
  return g;
}

// ---------- GLB ----------
const gltfLoader = new GLTFLoader();
export async function loadGLB(source) {
  const buf = source instanceof Blob ? await source.arrayBuffer() : await (await fetch(source)).arrayBuffer();
  const gltf = await gltfLoader.parseAsync(buf, '');
  return gltf.scene;
}

/** Fits a loaded model into the real W x D x H box (per axis), sitting on the floor. */
export function fitToBox(object, W, D, H, wall) {
  object.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object);
  const size = box.getSize(new THREE.Vector3());
  const inner = new THREE.Group();
  inner.add(object);
  const sx = size.x > 1e-6 ? W / size.x : 1, sy = size.y > 1e-6 ? H / size.y : 1, sz = size.z > 1e-6 ? D / size.z : 1;
  object.scale.multiply(new THREE.Vector3(sx, sy, sz));
  object.updateMatrixWorld(true);
  const b2 = new THREE.Box3().setFromObject(object);
  const c = b2.getCenter(new THREE.Vector3());
  object.position.x -= c.x;
  object.position.y -= b2.min.y;
  object.position.z -= wall ? b2.min.z : c.z;
  object.traverse(o => { if (o.isMesh) { o.castShadow = o.receiveShadow = true; } });
  return inner;
}

// ---------- entry point ----------
const imageCache = new Map();
export function loadImage(src) {
  if (!src) return Promise.resolve(null);
  if (imageCache.has(src)) return imageCache.get(src);
  const p = new Promise(resolve => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });
  imageCache.set(src, p);
  return p;
}

/**
 * Returns a Group for the item's model at real size. `assets` gives access to stored files:
 * { glb: Blob|null, image: HTMLImageElement|HTMLCanvasElement|null }.
 */
export async function buildModel(item, assets = {}) {
  const W = M(item.dims.w), D = M(item.dims.d), H = M(item.dims.h);
  const wall = CATEGORIES[item.category]?.mount === 'wall';
  const kind = item.model?.kind || 'shape';
  if (kind === 'glb' && assets.glb) {
    try { return fitToBox(await loadGLB(assets.glb), W, D, H, wall); } catch (e) { console.warn('model failed, drawing the shape instead', e); }
  }
  if (kind === 'photo' && assets.image) return photo(W, D, H, item, assets.image);
  switch (item.category) {
    case 'sofa': return sofa(W, D, H, item);
    case 'armchair': return sofa(W, D, H, item, 1);
    case 'chair': return W > 0.62 ? sofa(W, D, H, item, 1) : chair(W, D, H, item);
    case 'bed': return bed(W, D, H, item);
    case 'table': return table(W, D, H, item, false);
    case 'coffee-table': return table(W, D, H, item, true);
    case 'shelf': return shelf(W, D, H, item);
    case 'cabinet': return cabinet(W, D, H, item);
    case 'lamp': return lamp(W, D, H, item);
    case 'plant': return plant(W, D, H, item);
    case 'rug': return rug(W, D, H, item, assets.photoForTexture || null);
    case 'art': return art(W, D, H, item, assets.image || null);
    case 'mirror': return mirror(W, D, H, item);
    case 'tv': return tv(W, D, H, item);
    case 'decor': return decor(W, D, H, item);
    default:
      return assets.image ? photo(W, D, H, item, assets.image) : box(W, D, H, item);
  }
}

export function disposeObject(obj) {
  obj.traverse(o => {
    if (o.geometry) o.geometry.dispose();
    const mats = Array.isArray(o.material) ? o.material : o.material ? [o.material] : [];
    for (const m of mats) { for (const k of ['map', 'alphaMap', 'normalMap', 'roughnessMap', 'metalnessMap', 'emissiveMap']) m[k]?.dispose?.(); m.dispose(); }
  });
}
